// Buffer Freeze Mechanism (via ostrstream wrapper)
std::ostrstream os;
os << "Data payload" << std::ends;

// os.str() calls strstreambuf::freeze(true)
// and returns the managed buffer pointer.
char* persistent_buffer = os.str();

// os destructor executes. Since frozen=true,
// 'persistent_buffer' is NOT automatically deleted.

// User MUST manually release memory allocated by strstreambuf
delete[] persistent_buffer;
